public class RebirthStationCompletionOriginalScope{public static StringComparison PathComparison=>StringComparison.OrdinalIgnoreCase;public static int Epoch;private readonly int epoch;private readonly TileEntityWorkstation station;private RebirthStationCompletionOriginalScope(TileEntityWorkstation s){epoch=Epoch;station=s;}public bool IsCurrent()=>epoch==Epoch&&station!=null;public static bool TryCapture(TileEntityWorkstation s,RecipeQueueItem a,out RebirthStationCompletionOriginalScope scope){scope=new RebirthStationCompletionOriginalScope(s);Hooks.Capture?.Invoke();return scope.IsCurrent();}}
public static class RebirthStationCompletionReceipt{public const string Prefix="receipt.";public sealed class Identity{public int Count;}public static bool TryReadIdentity(CraftCompleteData r,out Identity id){id=new Identity{Count=r.CraftedItemStack.count};return true;}}
public static class RebirthStationCompletionCapture{
 public sealed class OutputObservation{private readonly ItemStack[] before;private readonly TileEntityWorkstation station;private readonly RecipeQueueItem active;public readonly RebirthStationCompletionOriginalScope Original;public OutputObservation(ItemStack[] b,RebirthStationCompletionOriginalScope o,TileEntityWorkstation s){before=b;Original=o;station=s;active=s.Queue.Last();}public bool Matches(TileEntityWorkstation s,CraftCompleteData r)=>ReferenceEquals(s,station)&&ReferenceEquals(s.Queue.Last(),active)&&Original.IsCurrent()&&RebirthStationOutputDelta.Matches(before,s.Output,r);}
 public static bool TryBuild(TileEntityWorkstation s,int actor,ItemValue v,string recipe,string scrap,int xp,int count,out CraftCompleteData row){row=new CraftCompleteData{CraftedItemStack=new ItemStack(v.Clone(),count),CrafterEntityID=actor,RecipeName=recipe,ItemScrapped=scrap,CraftExpGain=xp,RecipeUsedCount=1};return true;}
 public static bool TryObserveBefore(TileEntityWorkstation s,int actor,ItemValue v,string recipe,string scrap,int xp,int count,out OutputObservation o){RebirthStationCompletionOriginalScope.TryCapture(s,s.Queue.Last(),out var scope);o=new OutputObservation(ItemStack.Clone(s.Output),scope,s);return scope.IsCurrent();}
