public class RebirthStationNativeQueueSnapshot{RecipeQueueItem row;Recipe recipe;short count;int actor;public static bool TryCapture(System.Collections.Generic.IList<RecipeQueueItem> q,out RebirthStationNativeQueueSnapshot s){s=new RebirthStationNativeQueueSnapshot{row=q[q.Count-1],recipe=q[q.Count-1].Recipe,count=q[q.Count-1].Multiplier,actor=q[q.Count-1].StartingEntityId};return true;}public bool Matches(System.Collections.Generic.IList<RecipeQueueItem> q)=>q.Count==1&&ReferenceEquals(q[0],row)&&ReferenceEquals(row.Recipe,recipe)&&row.Multiplier==count&&row.StartingEntityId==actor;}
